item.text:
{
  "phenomenon": "两名住宅租客均自述提前一个月告知不续租，交房时出租方以房屋或家具状况为由拒退押金。租客随后分别尝试线上调解或向其他部门求助，最终都向法院递交材料。进入法院程序后，出租方重新联系租客并要求撤诉。其中一名租客明确说已收到押金转账，另一名只写明出租方愿意退款、自己寄出了撤诉材料。",
  "search_focus": "开放检索后选定住宅租赁期满不续租时的押金争议，优先比较能从提前通知追溯到交房、协商、向法院递交材料及后续处置的亲历事件。两案的共同条件来自租客自述，包括事先通知、交房时出现损耗争议、押金最初未退。按时告知并依约交房后可退押金，是其中一案记载的签约时预期。另一案未见合同全文，两案的损耗归属也未独立核实，因此无法判断该预期在两案中是否同等适用。",
  "sources": [
    {
      "url": "https://www.v2ex.com/t/1133419",
      "kind": "公开论坛评论区当事人自述",
      "supports": "第92楼，网页正文第252—260行。可定位提前告知、交房拒退、线上立案受阻、调解未果、线下立案及寄出撤诉材料的顺序。",
      "limits": "只有租客一方的回顾。明确写了对方愿意退款，未写明到账、金额或法院最终处理结果。该事件出自评论区，与主帖求助者的事件分别处理。"
    },
    {
      "url": "https://www.jiemian.com/article/5151522.html",
      "kind": "媒体刊载的第一人称亲历叙述",
      "supports": "文章中段关于租客起诉后收到退款的第一人称小节，网页正文第264—332行。第284—305行记录先前的退押金条件与交房争议，第307—332行记录求助、递交材料、对方再联系及转账。页面后段重复刊载同一叙述，按一个事件计。",
      "limits": "媒体编发了租客自述，文中提到截图和出警记录。本次核对限于公开正文，未独立验证合同、截图、出警记录或转账凭证。正文没有交代法院是否准许撤诉，也未给出足以重建全部款项结算的明细。"
    }
  ],
  "event_packet": {
    "sources": {
      "S1": "https://www.v2ex.com/t/1133419",
      "S2": "https://www.jiemian.com/article/5151522.html"
    },
    "events": [
      {
        "identity": "E1，论坛评论区的住宅租客，期满不续租。发帖日期为2025年5月，事件具体日期未载。",
        "facts": [
          {
            "source_id": "S1",
            "statement": "租客称自己提前一个月告知不续租。交房当天，出租方以台面开裂和床垫塌陷为由拒退押金，租客认为损耗在自己入住前已存在。",
            "use": "共同条件与交房争议，第92楼、网页第252—253行。",
            "key": true,
            "status": "single_account"
          },
          {
            "source_id": "S1",
            "statement": "自行沟通未果后，租客尝试线上立案，因缺少对方身份材料受阻。随后参加线上调解，拒绝承担出租方提出的全部修复要求。",
            "use": "立案前的行动与分歧，第254—257行。",
            "key": true,
            "status": "single_account"
          },
          {
            "source_id": "S1",
            "statement": "租客改走线下渠道，经法院出函取得身份材料，再递交材料并取得立案回执。",
            "use": "从线上受阻到线下立案，第258—259行。",
            "key": true,
            "status": "single_account"
          },
          {
            "source_id": "S1",
            "statement": "取得回执后，租客在朋友圈发文。几天后出租方联系租客，表示愿意退款并请求撤诉。租客称后来寄出了撤诉材料。",
            "use": "记录法院程序、公开表达和对方联系的先后，第259—260行。",
            "key": true,
            "status": "single_account"
          },
          {
            "source_id": "S1",
            "statement": "押金是否实际到账、到账金额和法院是否准许撤诉均未得到确认。",
            "use": "结果缺口，第259—260行。",
            "key": true,
            "status": "unverified"
          }
        ]
      },
      {
        "identity": "E2，媒体刊载亲历叙述中的住宅租客，期满不续租。出租方为二房东，与E1属于不同租赁关系。",
        "facts": [
          {
            "source_id": "S2",
            "statement": "租客称二房东事先说明，提前一个月告知不续租且家具无损坏时全额退押金。租住约11个月后，租客告知不续租。双方随后约定带人看房需事先联系。",
            "use": "对押金退还的事先预期及交房前互动，网页第284—299行。",
            "key": true,
            "status": "single_account"
          },
          {
            "source_id": "S2",
            "statement": "租客称自己在验收前打扫并录像。二房东以未交备用钥匙影响看房、家具出现磨损为由拒退押金，并要求另付维修费。",
            "use": "交房时双方的具体行为与争议，第301—305行。",
            "key": true,
            "status": "single_account"
          },
          {
            "source_id": "S2",
            "statement": "租客报警，并联系市场监管部门和市长热线，随后向法院起诉。她称递交了沟通截图、录音和出警记录。",
            "use": "核对先求助、再递交材料的过程，第307—324行。",
            "key": true,
            "status": "single_account"
          },
          {
            "source_id": "S2",
            "statement": "租客称约在递交材料一个月后，二房东恢复联系。双方协商后，对方通过微信退还押金、下调维修费，并要求撤诉。租客明确表示收到钱。",
            "use": "实际到账的自述与对方提出的条件，第324—332行。",
            "key": true,
            "status": "single_account"
          }
        ]
      }
    ],
    "sensitivity": "涉及私人租赁与纠纷。摘要省去姓名、账号、住址、公司名称及证件信息，以事件编号和正文位置支持复核。公开原链接仍可能指向当事人的自我披露。两案是个案材料，出租方类型、城市、时期、争议项目与前置求助不同。两案的材料也不足以区分法院程序、同期沟通及其他行动分别产生的影响，或估计此类退款的普遍程度。"
  },
  "search_log": {
    "method": "原生网页搜索及正文定位。逐条计入10次查询、3次正文查找和3次打开，共16次网页动作。",
    "queries": [
      {"query": "site:zhihu.com 亲历 租房 押金 退还 起诉 我 房东 经历", "outcome": "出现未交代处理结果的咨询和偏题内容。"},
      {"query": "site:douban.com/group/topic 房东 不退押金 我 起诉 调解 后续", "outcome": "找到合租水电争议和押金风险自述，公开正文未见押金处理结局。"},
      {"query": "site:tieba.baidu.com 房东 不退 押金 我 起诉 调解 已退", "outcome": "命中聚合页，多为求助或称已经起诉、尚待处理的条目。"},
      {"query": "site:xiaohongshu.com 退租 不退押金 起诉 成功 亲身经历", "outcome": "返回偏题内容，本轮没有取得相关公开原帖正文。"},
      {"query": "\"押金\" \"撤诉\" 租房 我 房东 退押金 经历 论坛 V2EX 知乎 豆瓣", "outcome": "定位V2EX候选和新闻转载线索。"},
      {"query": "site:v2ex.com 退租 押金 更新 已退 房东", "outcome": "找到第92楼的第一人称事件。不同域名下同一帖视为镜像。"},
      {"query": "site:douban.com/group/topic \"退押金\" \"已解决\" 房东 退租", "outcome": "本轮未取得同时包含关键过程与结局的可核验候选。"},
      {"query": "site:zhihu.com \"退押金\" \"撤诉\" 房东 我 租房", "outcome": "同批结果提供媒体第一人称正文线索，未取得质量相当的知乎亲历正文。"},
      {"query": "site:weibo.com 退租 房东 不退押金 起诉 退了 我的", "outcome": "返回报道、普法和话题结果。网页工具同时报告微博域名存在 robots.txt 访问限制，未纳入微博候选。"},
      {"query": "site:xiaoheihe.cn 房东 不退押金 退租 维权", "outcome": "本轮未获得可定位的相关亲历正文。"}
    ],
    "body_checks": [
      {"action": "查找并打开V2EX正文第92楼", "url": "https://www.v2ex.com/t/1133419", "outcome": "查找和打开各一次，核对第252—260行，纳入E1。"},
      {"action": "查找退款段并打开交房段", "url": "https://www.jiemian.com/article/5151522.html", "outcome": "查找和打开各一次，核对第264—332行。页面内重复段落合并，纳入E2。"},
      {"action": "在羊城晚报版面PDF查找空调卡段落", "url": "https://ep.ycwb.com/epaper/ycwb/resfile/2025-11-20/A03/ycwb20251120A03.pdf", "outcome": "页面可访问，文本查找未命中。"},
      {"action": "打开重庆晨报版面PDF核对同一报道", "url": "https://epaper.cqcb.com/attachment/202511/21/cba2f782-60fe-42b9-aca4-1873f8e1a613.pdf", "outcome": "第89—90行可定位当事人的部分退款陈述。与其他报纸的同一事件合并处理。公开段落对交房争议和起诉前互动的记录较少，未纳入最终配对。"}
    ]
  }
}
